#include <algorithm>
#include <array>
#include <cmath>
#include <cstdint>
#include <iostream>
#include <map>
#include <numeric>
#include <stdexcept>
#include <vector>
using namespace std;using Rows=vector<unsigned>;using Z=long long;
void check(bool p,const char*s){if(!p)throw runtime_error(s);}
int bit(unsigned b){return __builtin_ctz(b);}
int rankM(const Rows&M){int t=M.size();vector<int>mate(t,-1);auto dfs=[&](auto&&self,int i,unsigned&seen)->bool{for(int j=0;j<t;j++)if((M[i]>>j&1)&&!(seen>>j&1)){seen|=1<<j;if(mate[j]<0||self(self,mate[j],seen)){mate[j]=i;return true;}}return false;};int ans=0;for(int i=0;i<t;i++){unsigned seen=0;ans+=dfs(dfs,i,seen);}return ans;}
Rows physical(const Rows&O,const Rows&M){int t=O.size(),r=2*t,full=(1<<t)-1;Rows a(r+1);for(int i=0;i<t;i++){a[i]=O[i];a[t+i]=(full^(1<<i)^O[i])<<t;a[t+i]|=1<<r;}for(int i=0;i<t;i++)for(int j=0;j<t;j++)if(M[i]>>j&1)a[i]|=1<<(t+j);else a[t+j]|=1<<i;a[r]=full;return a;}
array<Z,3> root_words(const Rows&T){int n=T.size(),root=n-1,N=1<<root;vector<Z>d(size_t(N)*4*n);auto A=[&](int m,int k,int v)->Z&{return d[(size_t(m)*4+k)*n+v];};A(0,1,root)=1;for(int v=0;v<root;v++)A(1<<v,0,v)=1;for(int m=0;m<N;m++)for(int k=0;k<=3;k++)for(int last=0;last<n;last++)if(Z x=A(m,k,last)){for(int v=0;v<root;v++)if(!(m>>v&1)&&(T[last]>>v&1))A(m|1<<v,k,v)+=x;if(last!=root&&k<3&&(T[last]>>root&1))A(m,k+1,root)+=x;}array<Z,3>a{};for(int k=1;k<=3;k++)for(int last=0;last<n;last++)a[k-1]+=A(N-1,k,last);return a;}
Z reverse_hp(const Rows&T){int n=T.size(),N=1<<n;Rows pred(n);for(int i=0;i<n;i++)for(int j=0;j<n;j++)if(T[j]>>i&1)pred[i]|=1<<j;vector<Z>d(size_t(N)*n);for(int i=0;i<n;i++)d[size_t(1<<i)*n+i]=1;for(int m=1;m<N;m++)for(int v=0;v<n;v++)if((m>>v&1)&&m!=(1<<v)){int rest=m^(1<<v);unsigned z=pred[v]&rest;while(z){unsigned b=z&-z;z-=b;d[size_t(m)*n+v]+=d[size_t(rest)*n+bit(b)];}}Z h=0;for(int v=0;v<n;v++)h+=d[size_t(N-1)*n+v];return h;}
Rows clone_last(const Rows&T,int r,int m){int n=T.size()-1;vector<int>old;for(int v=0;v<(int)T.size();v++)if(v!=r)old.push_back(v);Rows s(n+m);for(int i=0;i<n;i++)for(int j=0;j<n;j++)if(T[old[i]]>>old[j]&1)s[i]|=1<<j;for(int v=0;v<n;v++)for(int c=n;c<n+m;c++)if(T[r]>>old[v]&1)s[c]|=1<<v;else s[v]|=1<<c;for(int c=n;c<n+m;c++)for(int d=c+1;d<n+m;d++)s[c]|=1<<d;return s;}
bool strong(const Rows&T){int n=T.size();for(int s=0;s<n;s++){unsigned mask=1<<s,prior=0;while(prior!=mask){prior=mask;for(int v=0;v<n;v++)if(mask>>v&1)mask|=T[v];}if(mask!=(1u<<n)-1)return false;}return true;}
bool prime(Z H){int b=sqrt(H);vector<bool>is(b+1,true);if(b>=0)is[0]=false;if(b>=1)is[1]=false;for(int p=2;p<=b;p++)if(is[p]){if(H%p==0)return false;for(int k=p+p;k<=b;k+=p)is[k]=false;}return H>1;}

long long isomorphisms(const Rows&A,const Rows&B,bool fixroot){int n=A.size();if(B.size()!=A.size())return 0;vector<int>order(n),p(n,-1);iota(order.begin(),order.end(),0);auto candidates=[&](int u){vector<int>z;for(int v=0;v<n;v++)if(__builtin_popcount(A[u])==__builtin_popcount(B[v])&&(!fixroot||((u==n-1)==(v==n-1))))z.push_back(v);return z;};sort(order.begin(),order.end(),[&](int u,int v){return candidates(u).size()<candidates(v).size();});long long total=0;auto go=[&](auto&&self,int depth,unsigned used)->void{if(depth==n){total++;return;}int u=order[depth];for(int v:candidates(u))if(!(used>>v&1)){bool ok=true;for(int k=0;k<depth;k++){int w=order[k];if((A[u]>>w&1)!=(B[v]>>p[w]&1)){ok=false;break;}}if(ok){p[u]=v;self(self,depth+1,used|(1<<v));p[u]=-1;}}};go(go,0,0);return total;}
int main(){vector<Rows>sources72;map<Z,int>amplitudes;long long total=0,r2=0;for(int t=0;t<=4;t++){vector<pair<int,int>>outer,mat;for(int i=0;i<t;i++){for(int j=i+1;j<t;j++)outer.push_back({i,j});for(int j=i;j<t;j++)mat.push_back({i,j});}vector<int>hist(t+1);map<Z,int>local;for(int om=0;om<(1<<(int)outer.size());om++){Rows O(t);for(int k=0;k<(int)outer.size();k++){auto[i,j]=outer[k];if(om>>k&1)O[i]|=1<<j;else O[j]|=1<<i;}for(int mm=0;mm<(1<<(int)mat.size());mm++){Rows M(t);for(int k=0;k<(int)mat.size();k++)if(mm>>k&1){auto[i,j]=mat[k];M[i]|=1<<j;M[j]|=1<<i;}total++;int rank=rankM(M);hist[rank]++;if(rank!=2)continue;r2++;auto a=root_words(physical(O,M));if(a[1]==3*a[2]&&a[0]==3*a[2]+1){amplitudes[a[2]]++;local[a[2]]++;if(a[2]==72)sources72.push_back(physical(O,M));}}}cout<<"physical_order "<<2*t+1<<" rank_histogram";for(auto c:hist)cout<<' '<<c;cout<<" positive_amplitudes";for(auto[A,c]:local)cout<<' '<<A<<':'<<c;cout<<'\n';}check(total==66067&&r2==4146,"physical universe size");check(amplitudes.size()==2&&amplitudes.count(72)&&amplitudes.count(200),"independent exact amplitude support");Rows source={414,260,8,50,294,327,415,318,12};int root=4;Rows core=clone_last(source,root,1);for(const auto&T:sources72)check(isomorphisms(T,core,true)==1,"unique rooted equality core");check(isomorphisms(core,core,false)==1,"rigid unmarked equality core");vector<int>clockroots;for(int r=0;r<9;r++){Rows last=clone_last(source,r,1);auto coeff=root_words(last);vector<int>O,I;for(int v=0;v<9;v++)if(v!=r)((source[r]>>v&1)?O:I).push_back(v);Rows M(max(O.size(),I.size()));for(int i=0;i<(int)O.size();i++)for(int j=0;j<(int)I.size();j++)if(source[O[i]]>>I[j]&1)M[i]|=1<<j;if(rankM(M)==2&&coeff==array<Z,3>{217,216,72})clockroots.push_back(r);}check(clockroots==vector<int>{4},"unique equality clock root");cout<<"equality amplitude72 physical_presentations="<<sources72.size()<<" rooted_core_classes=1 unmarked_automorphisms=1 clock_root=4\n";auto a=root_words(clone_last(source,root,1));check(a==array<Z,3>{217,216,72},"direct attaining run profile");for(int m:{1,2,3,4,5,6,7,8}){Rows T=clone_last(source,root,m);Z power=1;for(int k=0;k<m;k++)power*=3;Z h=reverse_hp(T);check(h==72*power+1&&strong(T),"physical reverse-DP clone count and strongness");int n=T.size();vector<int>tau(n);for(int i=0;i<8;i++)tau[i]=7-i;for(int c=8;c<n;c++)tau[c]=8+n-1-c;for(int i=0;i<n;i++)for(int j=0;j<n;j++)check((T[i]>>j&1)==(T[tau[j]]>>tau[i]&1),"physical clone anti-involution");if(m==5||m==6||m==8)check(prime(h),"independent sieve primes");cout<<"clone m="<<m<<" H="<<h<<" prime="<<prime(h)<<" rows";for(auto row:T)cout<<' '<<row;cout<<'\n';}check(prime(31),"prime quotient31");for(int k=0;k<5;k++){Z x=6;for(int i=0;i<k;i++)x*=9;if(k==0)check((x+1)==7&&(x*x-x+1)==31,"first factorization");if(k<5&&k>0)check(x+1>7&&x*x-x+1>7,"later factors exceed7");}cout<<"PASS physical_sources="<<total<<" rank2_direct_word_checks="<<r2<<" amplitude72_presentations="<<amplitudes[72]<<" amplitude200_presentations="<<amplitudes[200]<<'\n';}
